import{_ as s,o as a,c as e,a2 as i}from"./chunks/framework.DGu13UIe.js";const n="/bagent/install.png",c=JSON.parse('{"title":"安装插件（开箱即用）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install-plugin.md","filePath":"guide/install-plugin.md"}'),r={name:"guide/install-plugin.md"};function l(h,t,o,p,d,g){return a(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="安装插件-开箱即用" tabindex="-1">安装插件（开箱即用） <a class="header-anchor" href="#安装插件-开箱即用" aria-label="Permalink to &quot;安装插件（开箱即用）&quot;">​</a></h1><p>不想 clone 仓库、不想 <code>npm run compile</code>？从 <strong>GitHub Release</strong> 下载 <strong>bagent</strong> 插件，配好 Key 就能在 Cursor / VS Code 里用完整版 Code Agent（diff 预览 + Accept 写盘）。</p><p><a href="https://github.com/SyncLionPaw/bagent/releases/latest" target="_blank" rel="noreferrer">GitHub Releases → 下载最新版</a></p><p>固定文件名：<strong><code>bagent-plugin.vsix</code></strong>（在 Release 资源里）。</p><hr><h2 id="你需要什么" tabindex="-1">你需要什么 <a class="header-anchor" href="#你需要什么" aria-label="Permalink to &quot;你需要什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>编辑器</td><td><a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">VS Code</a> 或 <a href="https://cursor.com/" target="_blank" rel="noreferrer">Cursor</a></td></tr><tr><td>DeepSeek</td><td><a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">API Key</a>（必填）</td></tr><tr><td>Tavily</td><td><a href="https://tavily.com/" target="_blank" rel="noreferrer">API Key</a>（可选，用于联网搜索）</td></tr><tr><td>Node</td><td><strong>不需要</strong>（已打进 .vsix）</td></tr></tbody></table><hr><h2 id="_1-安装-vsix" tabindex="-1">1. 安装 .vsix <a class="header-anchor" href="#_1-安装-vsix" aria-label="Permalink to &quot;1. 安装 .vsix&quot;">​</a></h2><p><strong>图形界面</strong></p><p><img src="'+n+`" alt="扩展面板 → ⋯ → 从 VSIX 安装…"></p><ol><li>打开 <a href="https://github.com/SyncLionPaw/bagent/releases/latest" target="_blank" rel="noreferrer">Releases</a>，下载 <strong><code>bagent-plugin.vsix</code></strong></li><li>扩展面板 → 右上角 <strong><code>⋯</code></strong> → <strong>从 VSIX 安装…</strong>（Install from VSIX）</li><li>选中刚下载的文件</li></ol><p>装好后左侧 <strong>已安装</strong> 里会出现 <strong>bagent</strong>（小黄人图标）；右侧辅助栏可打开 Agent 对话。</p><p><strong>命令行</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Cursor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cursor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-extension</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/bagent-plugin.vsix</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># VS Code</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-extension</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/bagent-plugin.vsix</span></span></code></pre></div><p>装好后侧边栏会出现 <strong>bagent</strong>（右侧辅助栏），或命令面板搜 <strong>bagent: 打开 Agent 面板</strong>。</p><hr><h2 id="_2-配置-api-key" tabindex="-1">2. 配置 API Key <a class="header-anchor" href="#_2-配置-api-key" aria-label="Permalink to &quot;2. 配置 API Key&quot;">​</a></h2><p>在终端执行（路径可改）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bagent</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sk-你的DeepSeek密钥&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bagent/deepseek-api-key</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 可选：联网搜索</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;tvly-你的Tavily密钥&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bagent/tavily-api-key</span></span></code></pre></div><p>也可以用环境变量（优先于文件）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-...&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TAVILY_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tvly-...&quot;</span></span></code></pre></div><p>插件里输入 <code>/config</code> 可查看当前 Key 是否读到。</p><hr><h2 id="_3-开始使用" tabindex="-1">3. 开始使用 <a class="header-anchor" href="#_3-开始使用" aria-label="Permalink to &quot;3. 开始使用&quot;">​</a></h2><ol><li>用 Cursor / VS Code <strong>打开你的项目文件夹</strong>（Agent 的 cwd 即工作区根目录）</li><li>打开 bagent 侧栏，像聊天一样提问</li><li>改文件时会打开 <strong>diff 预览</strong>；在编辑器标题栏点 <strong>Accept</strong> 才写盘</li></ol><p>想从零理解原理、自己改代码 → <a href="/bagent/chapters/01-deepseek.html">第 1 课</a> 或 <a href="/bagent/guide/environment.html">环境准备</a> 走完整课程。</p><hr><h2 id="更新插件" tabindex="-1">更新插件 <a class="header-anchor" href="#更新插件" aria-label="Permalink to &quot;更新插件&quot;">​</a></h2><p>到 <a href="https://github.com/SyncLionPaw/bagent/releases/latest" target="_blank" rel="noreferrer">Releases</a> 下新版 <code>bagent-plugin.vsix</code>，再次「从 VSIX 安装」即可覆盖（或先卸载旧版 <strong>bagent</strong>）。</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>处理</th></tr></thead><tbody><tr><td>侧栏没反应</td><td>命令面板运行 <strong>bagent: 打开 Agent 面板</strong></td></tr><tr><td>提示找不到 Key</td><td>检查 <code>~/.bagent/deepseek-api-key</code> 或 <code>DEEPSEEK_API_KEY</code></td></tr><tr><td>没有联网搜索</td><td>配置 Tavily Key；没有则本地工具仍可用</td></tr><tr><td>想自己改插件源码</td><td>克隆仓库，跟 <a href="/bagent/chapters/54-diagnostics.html">第 54 课</a> 用 F5 开发</td></tr></tbody></table>`,33)])])}const b=s(r,[["render",l]]);export{c as __pageData,b as default};
